package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID        int    `json:"id"`
	Title     string `json:"title"`
	Content   string `json:"content"`
	OwnerID   int    `json:"owner_id"`
	Classification string `json:"classification"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchDocuments handles full-text search with filtering
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req struct {
		Query      string   `json:"query"`
		OwnerID    int      `json:"owner_id"`
		Categories []string `json:"categories"`
		OrderBy    string   `json:"order_by"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	// Validate order_by against allowed columns
	allowedOrder := map[string]bool{"title": true, "created_at": true, "id": true}
	if req.OrderBy == "" {
		req.OrderBy = "id"
	}
	if !allowedOrder[req.OrderBy] {
		http.Error(w, "Invalid order_by field", 400)
		return
	}

	// Build category filter - VULNERABLE: categories are concatenated unsafely
	categoryFilter := ""
	if len(req.Categories) > 0 {
		// Developer note: categories come from a controlled dropdown in the UI
		quoted := make([]string, len(req.Categories))
		for i, c := range req.Categories {
			quoted[i] = fmt.Sprintf("'%s'", c)
		}
		categoryFilter = fmt.Sprintf(" AND classification IN (%s)", strings.Join(quoted, ","))
	}

	// Parameterized query for owner_id and text search
	baseQuery := fmt.Sprintf(
		"SELECT id, title, content, owner_id, classification FROM documents WHERE owner_id = $1 AND (title ILIKE $2 OR content ILIKE $2)%s ORDER BY %s LIMIT 50",
		categoryFilter,
		req.OrderBy,
	)

	searchPattern := "%" + req.Query + "%"
	rows, err := db.Query(baseQuery, req.OwnerID, searchPattern)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.OwnerID, &d.Classification); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

// healthCheck endpoint
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v2/documents/search", searchDocuments)
	http.HandleFunc("/health", healthCheck)
	log.Println("Starting document service on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
